        height=gfx_driver->h;
    }
    rectfill(screen,0,0,width,height,color);
    solid_mode();
    draw_sprite(screen,data[88].dat,103,200);
    textprintf_centre_ex(screen,data[51].dat,320,220,-1,-1,"%s",text);
}

